import{_ as o,o as a,c as t,a2 as l}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Slack","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/channels/slack.md","filePath":"ja/integrations/channels/slack.md","lastUpdated":1792323081000}'),i={name:"ja/integrations/channels/slack.md"};function c(r,e,s,n,d,h){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="slack" tabindex="-1">Slack <a class="header-anchor" href="#slack" aria-label="Permalink to &quot;Slack&quot;">​</a></h1><p>Memoh Bot を Slack につなぎます。DM の受信、チャンネルやスレッドへの参加、添付ファイルの読み取り、ファイルの送信、ストリーミング返信に対応します。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>アプリをインストールできる Slack ワークスペースと、<a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">Slack API コンソール</a> へのアクセス。</li><li>Memoh Bot。チャネルはその <strong>プラットフォーム</strong> タブで設定します。</li></ul><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><h3 id="_1-slack-api-コンソールでアプリを作成する" tabindex="-1">1. Slack API コンソールでアプリを作成する <a class="header-anchor" href="#_1-slack-api-コンソールでアプリを作成する" aria-label="Permalink to &quot;1. Slack API コンソールでアプリを作成する&quot;">​</a></h3><ol><li><a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">Slack API コンソール</a> を開き、<strong>Create New App</strong> をクリックします。</li><li>Bot をインストールするワークスペースを選択します。</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>アプリの設定ページは開いたままにしておいてください。ステップ 2 から 5 はすべてここで行います。</p></div><h3 id="_2-slack-api-コンソールで-socket-mode-を有効にする" tabindex="-1">2. Slack API コンソールで Socket Mode を有効にする <a class="header-anchor" href="#_2-slack-api-コンソールで-socket-mode-を有効にする" aria-label="Permalink to &quot;2. Slack API コンソールで Socket Mode を有効にする&quot;">​</a></h3><p>Memoh の Slack アダプターは Socket Mode を使うため、Bot token に加えて app-level token も必要です。</p><ol><li><strong>Basic Information</strong> で <strong>Socket Mode</strong> を有効にします。</li><li><strong>App-Level Token</strong> を作成し、scope に <code>connections:write</code> をチェックします。</li><li>生成された token をコピーします。<code>xapp-</code> で始まります。</li></ol><h3 id="_3-slack-api-コンソールで-bot-token-scopes-を追加する" tabindex="-1">3. Slack API コンソールで Bot Token Scopes を追加する <a class="header-anchor" href="#_3-slack-api-コンソールで-bot-token-scopes-を追加する" aria-label="Permalink to &quot;3. Slack API コンソールで Bot Token Scopes を追加する&quot;">​</a></h3><p><strong>OAuth &amp; Permissions</strong> で、Slack アダプターに必要な scope を追加します。</p><ul><li><code>app_mentions:read</code>：チャンネル内での Bot への @メンションを受信</li><li><code>channels:history</code>：パブリックチャンネルのメッセージを読む</li><li><code>groups:history</code>：プライベートチャンネルのメッセージを読む</li><li><code>im:history</code>：DM を読む</li><li><code>mpim:history</code>：グループ DM を読む</li><li><code>chat:write</code>：返信とスレッドメッセージを送信</li><li><code>files:read</code>：アップロードされたファイルや画像を読む</li><li><code>files:write</code>：ファイルを送信</li><li><code>reactions:write</code>：リアクションの追加／削除</li></ul><p>会話名やメタデータを Memoh でより完全に表示したい場合は、次も追加することをおすすめします。</p><ul><li><code>channels:read</code></li><li><code>groups:read</code></li><li><code>im:read</code></li><li><code>mpim:read</code></li></ul><h3 id="_4-slack-api-コンソールでイベントを購読する" tabindex="-1">4. Slack API コンソールでイベントを購読する <a class="header-anchor" href="#_4-slack-api-コンソールでイベントを購読する" aria-label="Permalink to &quot;4. Slack API コンソールでイベントを購読する&quot;">​</a></h3><p><strong>Event Subscriptions</strong> で bot events を有効にし、Slack アダプターが処理する受信イベントを追加します。</p><ul><li><code>app_mention</code></li><li><code>message.channels</code></li><li><code>message.groups</code></li><li><code>message.im</code></li><li><code>message.mpim</code></li></ul><h3 id="_5-slack-api-コンソールでアプリをワークスペースにインストールする" tabindex="-1">5. Slack API コンソールでアプリをワークスペースにインストールする <a class="header-anchor" href="#_5-slack-api-コンソールでアプリをワークスペースにインストールする" aria-label="Permalink to &quot;5. Slack API コンソールでアプリをワークスペースにインストールする&quot;">​</a></h3><ol><li><strong>OAuth &amp; Permissions</strong> で <strong>Install to Workspace</strong> をクリックします。</li><li>権限の確認画面で内容を確認し、承認します。</li><li><strong>Bot User OAuth Token</strong> をコピーします。<code>xoxb-</code> で始まります。</li></ol><h3 id="_6-memoh-で-slack-チャネルを追加する" tabindex="-1">6. Memoh で Slack チャネルを追加する <a class="header-anchor" href="#_6-memoh-で-slack-チャネルを追加する" aria-label="Permalink to &quot;6. Memoh で Slack チャネルを追加する&quot;">​</a></h3><ol><li>Bot の詳細ページを開き、<strong>プラットフォーム</strong> タブに移動します。</li><li><strong>Add Channel</strong> をクリックし、<strong>Slack</strong> を選択します。</li><li>次を入力します。 <ul><li><strong>Bot Token</strong>：<code>xoxb-</code> で始まる token</li><li><strong>App-Level Token</strong>：<code>xapp-</code> で始まる token</li></ul></li><li><strong>Save and Enable</strong> をクリックします。</li></ol><h3 id="_7-slack-で-bot-を会話に追加する" tabindex="-1">7. Slack で Bot を会話に追加する <a class="header-anchor" href="#_7-slack-で-bot-を会話に追加する" aria-label="Permalink to &quot;7. Slack で Bot を会話に追加する&quot;">​</a></h3><p>チャネルを有効にしたあとも、この Slack アプリを使いたい会話に参加させておく必要があります。</p><ul><li>DM：アプリとの DM を開いてメッセージを送信します。</li><li>パブリックチャンネル：Bot をチャンネルに招待します。</li><li>プライベートチャンネル：インストール後に明示的にチャンネルへ招待します。</li></ul><h2 id="認証情報" tabindex="-1">認証情報 <a class="header-anchor" href="#認証情報" aria-label="Permalink to &quot;認証情報&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td><strong>Bot Token</strong></td><td>ワークスペースへのインストール後にコピーする <strong>Bot User OAuth Token</strong>（<code>xoxb-</code> で始まる）。</td></tr><tr><td><strong>App-Level Token</strong></td><td>Socket Mode 用に作成した、<code>connections:write</code> scope 付きの token（<code>xapp-</code> で始まる）。</td></tr></tbody></table><p>2 つの token は、同じ Slack アプリ・同じワークスペースのものでなければなりません。</p><h2 id="動作確認" tabindex="-1">動作確認 <a class="header-anchor" href="#動作確認" aria-label="Permalink to &quot;動作確認&quot;">​</a></h2><p>Bot をチャンネルに招待して @メンション付きで <code>/help</code> を送るか、DM で <code>/help</code> を送ります。Bot がコマンド一覧を返せば、チャネルは機能しています。</p><h2 id="グループチャット" tabindex="-1">グループチャット <a class="header-anchor" href="#グループチャット" aria-label="Permalink to &quot;グループチャット&quot;">​</a></h2><p>Slack ではチャンネルがグループチャットに相当します。Bot をパブリックまたはプライベートチャンネルに招待し、@メンションすると会話できます。返信はスレッドで続けられます。スレッドに対応しているのは Slack チャネルだけです。</p><h2 id="無効化と認証情報の更新" tabindex="-1">無効化と認証情報の更新 <a class="header-anchor" href="#無効化と認証情報の更新" aria-label="Permalink to &quot;無効化と認証情報の更新&quot;">​</a></h2><p>Bot の <strong>プラットフォーム</strong> タブから、いつでもこのチャネルを無効化・削除できます。認証情報を更新するときは、<strong>Bot Token</strong> と <strong>App-Level Token</strong> のフィールドを更新して保存してください。</p><h2 id="faq" tabindex="-1">よくある質問 <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;よくある質問 {#faq}&quot;">​</a></h2><h3 id="why-two-tokens" tabindex="-1">なぜ token を 2 つ入力するのですか？ <a class="header-anchor" href="#why-two-tokens" aria-label="Permalink to &quot;なぜ token を 2 つ入力するのですか？ {#why-two-tokens}&quot;">​</a></h3><p>Memoh の Slack アダプターは Socket Mode を使います。<code>xoxb-</code> で始まる Bot token に加えて <code>xapp-</code> で始まる app-level token が必要で、両方が同じ Slack アプリ・同じワークスペースのものでなければなりません。</p><h3 id="cannot-read-files" tabindex="-1">Bot はメッセージを送れるのに、アップロードされた画像やファイルを読めない <a class="header-anchor" href="#cannot-read-files" aria-label="Permalink to &quot;Bot はメッセージを送れるのに、アップロードされた画像やファイルを読めない {#cannot-read-files}&quot;">​</a></h3><p><code>files:read</code> scope が有効になっているか確認してください。</p><h3 id="no-incoming-messages" tabindex="-1">接続はできているのに、受信メッセージがまったく届かない <a class="header-anchor" href="#no-incoming-messages" aria-label="Permalink to &quot;接続はできているのに、受信メッセージがまったく届かない {#no-incoming-messages}&quot;">​</a></h3><p><strong>Event Subscriptions</strong> の bot events と、対応する <code>history</code> 系 scope をもう一度確認してください。</p>',42)])])}const m=o(i,[["render",c]]);export{p as __pageData,m as default};
